/** Additional contemporary country profiles. Values are restrained editorial estimates. */
import type { AxisKey, ReferenceEntry, ReferenceSource } from './references';

type AxisEvidenceDetail = { sourceTitles: string[]; rationale: string };
type CountryEntry = ReferenceEntry & { axisEvidence: Partial<Record<AxisKey, AxisEvidenceDetail>> };

type FreedomStatus = 'Free' | 'Partly Free' | 'Not Free';
type ConstitutionalOrder = 'unitary' | 'devolved' | 'federal' | 'unknown';
type ReligionClause = 'secular' | 'traditional' | 'established' | 'unknown';

interface CountrySpec {
  id: string;
  name: string;
  constitution: string;
  constitutionTitle: string;
  constitutionPath?: string;
  freedomSlug?: string;
  freedom: FreedomStatus;
  order: ConstitutionalOrder;
  religion: ReligionClause;
  note: string;
}

interface HistoricalSpec {
  id: string;
  name: string;
  period: string;
  primaryTitle: string;
  primaryUrl: string;
  contextTitle: string;
  contextUrl: string;
  scores: Partial<Record<AxisKey, number>>;
  evidence: Partial<Record<AxisKey, 'high' | 'medium'>>;
  axisNotes: Partial<Record<AxisKey, string>>;
  rationale: string;
  caveats: string;
}

const source = (title: string, url: string, note: string): ReferenceSource => ({ title, url, note });
const axisKeys: readonly AxisKey[] = ['est', 'rep', 'pod', 'imi', 'dip', 'int', 'eco', 'con', 'com', 'rel', 'mor', 'tec'];

