const statusScore: Record<FreedomStatus, number> = { 'Free': 85, 'Partly Free': 55, 'Not Free': 15 };
const orderScore: Record<ConstitutionalOrder, number> = { unitary: 15, devolved: 30, federal: 90, unknown: 50 };
const religionScore: Record<ReligionClause, number> = { secular: 85, traditional: 60, established: 15, unknown: 50 };

function makeCountry(spec: CountrySpec): CountryEntry {
  const freedomTitle = `Freedom in the World 2025 — ${spec.name}`;
  const constitutionUrl = `https://www.constituteproject.org/constitution/${spec.constitutionPath ?? spec.constitution}?lang=en`;
  const freedomSlug = spec.freedomSlug ?? spec.id.replace(/-current-2025$/, '');
  const sources = [
    source(spec.constitutionTitle, constitutionUrl, 'Texto constitucional reproduzido em tradução pelo Comparative Constitutions Project; fonte para a forma territorial do Estado e a cláusula religiosa.'),
    source(freedomTitle, `https://freedomhouse.org/country/${freedomSlug}/freedom-world/2025`, 'Avaliação anual de direitos políticos e liberdades civis para 2024; usada apenas como orientação categórica, não como medição dos demais eixos.'),
  ];
  const vec: Record<AxisKey, number> = {
    est: orderScore[spec.order], rep: statusScore[spec.freedom], pod: 50, imi: 50,
    dip: 50, int: 50, eco: 50, con: 50, com: 50,
    rel: religionScore[spec.religion], mor: 50, tec: 50,
  };
  const axisEvidence: Partial<Record<AxisKey, AxisEvidenceDetail>> = {};
  const evidence: ReferenceEntry['evidence'] = {};
  if (spec.order !== 'unknown') {
    evidence.est = 'medium';
    axisEvidence.est = {
      sourceTitles: [spec.constitutionTitle],
      rationale: `A constituição define a estrutura territorial como ${spec.order === 'unitary' ? 'unitária' : spec.order === 'devolved' ? 'unitária com descentralização' : 'federal'}; a nota editorial aproxima esse desenho do polo correspondente, sem afirmar que o texto mede autonomia praticada.`,
    };
  }
  evidence.rep = 'medium';
  axisEvidence.rep = {
    sourceTitles: [freedomTitle],
    rationale: `A classificação narrativa de direitos políticos e liberdades civis como “${spec.freedom}” fundamenta somente um intervalo amplo (85, 55 ou 15), não uma pontuação psicométrica nem os outros eixos.`,
  };
  if (spec.religion !== 'unknown') {
    evidence.rel = 'medium';
    axisEvidence.rel = {
      sourceTitles: [spec.constitutionTitle],
      rationale: `A cláusula constitucional caracteriza o Estado como ${spec.religion === 'secular' ? 'secular ou sem religião oficial' : spec.religion === 'traditional' ? 'secular com reconhecimento constitucional de uma tradição religiosa' : 'com religião oficial'}; o valor descreve a norma estatal, não a religiosidade da população.`,
    };
  }
  return {
    id: spec.id,
    kind: 'country',
    category: 'country',
    name: spec.name,
    period: 'Instituições e políticas avaliadas, 2024–2025',
    vec,
    rationale: spec.note,
    caveats: 'O registro compara algumas características institucionais do Estado, nunca crenças de seus habitantes. Os demais eixos ficam em 50 por falta de evidência específica neste recorte; este perfil tem cobertura inferior a seis eixos e deve permanecer fora do ranking até revisão documental mais ampla.',
    sources,
    evidence,
    axisEvidence,
  };
}

