function makeHistorical(spec: HistoricalSpec): CountryEntry {
  const vec = Object.fromEntries(axisKeys.map(key => [key, spec.scores[key] ?? 50])) as Record<AxisKey, number>;
  const sources = [
    source(spec.primaryTitle, spec.primaryUrl, `Fonte documental relacionada ao recorte ${spec.period}; sustenta somente os eixos apontados na justificativa específica.`),
    source(spec.contextTitle, spec.contextUrl, 'Fonte de arquivo, pesquisa histórica ou contexto institucional para delimitar o período e confrontar o texto normativo.'),
  ];
  const axisEvidence: Partial<Record<AxisKey, AxisEvidenceDetail>> = {};
  for (const [axis, value] of Object.entries(spec.scores) as [AxisKey, number][]) {
    const detail = spec.axisNotes[axis];
    if (!detail || !spec.evidence[axis]) continue;
    axisEvidence[axis] = {
      sourceTitles: [spec.primaryTitle, spec.contextTitle],
      rationale: detail,
    };
  }
  return {
    id: spec.id,
    kind: 'country',
    category: 'historical-country',
    name: spec.name,
    period: spec.period,
    vec,
    rationale: spec.rationale,
    caveats: `${spec.caveats} Os eixos sem evidência direta permanecem em 50 como desconhecidos.`,
    sources,
    evidence: spec.evidence,
    axisEvidence,
  };
}

export const historicalCountriesAdditionalExpansion: CountryEntry[] = historicalSpecs.map(makeHistorical);
